/* List the side's generals (up to the first empty record), clear their
 * marks and draw the staff and division frames.
 */
void opeu_general_screen(uint8_t ds[65536], HostEvent event) {
  uint8_t a, b;
  PERSON  c;
  c = SIDE_RECORDS;
  b = a = 0;
  for (; b < 20; NEXT_PERSON(c), b++) {
    /* if/else break keeps the empty-record test at the top of the body. */
    if (FIELD(c, 0x12) != 0xff) {
      SET_LIST(a++, c);
      SET_COUNTER(c, 0);
      FIELD(c, 0x1e) &= 0xf8;
    } else
      break;
  }
  a++;
  SET_COUNTS(a);
  BACKDROP(SIDE == 0 ? 2 : 1);
  POSITION(0x23, 8);
  if (SIDE == 0)
    TEXT_COLOR(6);
  else
    TEXT_COLOR(5);
  PRINT(TITLE_FORMAT, SIDE_TITLE(SIDE));
  TEXT_COLOR(7);
  OUTLINE(0x100, 0x28, 0x13f, 0x76, 7);
  POSITION(0x29, 0x38);
  UI_TEXT(ROLE_NAME(0));
  OUTLINE(0x60, 0x28, 0x9f, 0x76, 7);
  POSITION(0x15, 0x38);
  UI_TEXT(ROLE_NAME(1));
  OUTLINE(0x1a0, 0x28, 0x1df, 0x76, 7);
  POSITION(0x3d, 0x38);
  UI_TEXT(ROLE_NAME(2));
  for (b = 0; b < 4; b++) {
    OUTLINE(b * 0xa0 + 0x10, 0x88, b * 0xa0 + 0x4f, 0xd6, 7);
    DIVISION_BOX(b);
  }
}

void opeu_reinforce_screen(uint8_t ds[65536], HostEvent event) {
  CLEAR_REINFORCE();
  ATTRIBUTE(4);
  POSITION(1, 0xe8);
  UI_TEXT(REINFORCE_TITLE);
  POSITION(1, 0x170);
  if (INPUT_MODE)
    UI_TEXT(MOUSE_HELP);
  else
    UI_TEXT(KEY_HELP);
  ATTRIBUTE(0);
  LIST_DIALOG(REINFORCE_DIALOG, 1, 3);
  REDRAW();
  REINFORCE_APPLY();
}

void opeu_play_screen(uint8_t ds[65536], HostEvent event) {
  ATTRIBUTE(4);
  POSITION(0x15, 0x170);
  UI_TEXT(PLAY_PROMPT);
  ATTRIBUTE(0);
  PLAY_DIALOG_RUN(PLAY_DIALOG, 7, 1);
  REDRAW();
}

/* For each side: back up its records, register every listed general and,
 * for a human-controlled side, repeat the screens until confirmed.
 */
void opeu_confirm_generals(uint8_t ds[65536], HostEvent event) {
  uint8_t a;
  PERSON  b;
  for (SIDE = 0; SIDE < 2; SIDE++) {
    COPY(SIDE_RECORDS, BACKUP, 0x26c);
    b = SIDE_RECORDS;
    /* if/else break gives C 6.0a's unrotated loop (increment first). */
    for (a = 0; a < 20; a++) {
      if (FIELD(b, 0x12) != 0xff) {
        PERSON_SLOT(a);
        PERSON_MARKS(b);
        NEXT_PERSON(b);
      } else
        break;
    }
    if (CONTROL(SIDE) == 1) {
      ATTRIBUTE(4);
      do {
        GENERAL_SCREEN();
        REINFORCE_SCREEN();
        PLAY_SCREEN();
        ATTRIBUTE(4);
        POSITION(0x14, 0x170);
      } while (!ASK(USE_PROMPT));
      ATTRIBUTE(0);
    }
  }
}

